package net.civeira.phylax.feature.access.userinvitation.domain;

public enum UserInvitationStatusOptions {

  /**
   * @autogenerated PropertyOptionsGenerator
   */
  PENDING,
  /**
   * @autogenerated PropertyOptionsGenerator
   */
  ACCEPTED,
  /**
   * @autogenerated PropertyOptionsGenerator
   */
  CANCELLED,
  /**
   * @autogenerated PropertyOptionsGenerator
   */
  EXPIRED;

  /**
   * The option for a value as it comes from the API (pass, PASS, in-progress...)
   *
   * @autogenerated PropertyOptionsGenerator
   * @param value The value, or null
   * @throws IllegalArgumentException If the value is not an option
   * @return The option, or null for an empty value
   */
  public static UserInvitationStatusOptions fromValue(String value)
      throws IllegalArgumentException {
    if (null == value || value.trim().isEmpty()) {
      return null;
    }
    String constant = value.trim().replace('-', '_').toUpperCase();
    for (UserInvitationStatusOptions option : values()) {
      if (option.name().equals(constant)) {
        return option;
      }
    }
    throw new IllegalArgumentException(
        "Unknown value " + value + " for UserInvitationStatusOptions");
  }
}
